"""Generated by solo-to-scale; edit `templates/tools/_s2s.py` in the plugin, then run upgrade.

Shared readers for the repo tools: config, registers, playbook, team mapping, founder items, slices.
Python 3 standard library only; runs on Linux, macOS and Windows.
"""
from __future__ import annotations

import fnmatch
import json
import re
import subprocess
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
ROW_ID = re.compile(r"^([A-Z]{1,3})-(\d+)$")
STATUSES = ("Approved", "Proposed", "Assumption", "Open")
ROLES = ("architect", "qa", "growth", "engineer", "product", "research")
FUNCTION_OF_ROLE = {"architect": "03 Architecture", "qa": "05 QA", "growth": "06 GTM", "engineer": "04 Engineering"}
DEFAULT_CFG: dict[str, Any] = {
    "claude_md_max_lines": 200, "pr_warn_lines": 400, "status_stale_days": 14,
    "slices_file": "founder/slices.json", "registers": ["founder/decisions.md", "specs/*/decisions.md"],
    "approved_words": ["Approved", "Confirmed"], "generated_paths": [],
}


def read(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except OSError:
        return ""


def config(root: Path = ROOT) -> dict[str, Any]:
    cfg = dict(DEFAULT_CFG)
    try:
        cfg.update(json.loads(read(root / ".claude" / "governance.json") or "{}"))
    except ValueError:
        pass
    return cfg


def project(root: Path = ROOT) -> dict[str, Any]:
    try:
        return json.loads(read(root / "founder" / "project.json") or "{}")
    except ValueError:
        return {}


def git(root: Path, *args: str) -> str | None:
    try:
        out = subprocess.run(["git", *args], cwd=root, capture_output=True, text=True, encoding="utf-8",
                             timeout=30, check=False)
    except (OSError, subprocess.SubprocessError):
        return None
    return out.stdout if out.returncode == 0 else None


def cells(line: str) -> list[str]:
    return [c.strip() for c in line.strip().strip("|").split("|")]


def tables(text: str) -> list[list[dict[str, str]]]:
    """Every markdown table as a list of rows keyed by lower-cased header."""
    out: list[list[dict[str, str]]] = []
    header: list[str] | None = None
    rows: list[dict[str, str]] = []
    for line in text.splitlines() + [""]:
        if line.strip().startswith("|"):
            if set(line.strip()) <= set("|-: "):
                continue
            c = cells(line)
            if header is None:
                header = [h.strip("*` ").lower() for h in c]
            else:
                rows.append({header[i] if i < len(header) else str(i): v for i, v in enumerate(c)})
        else:
            if header is not None:
                out.append(rows)
            header, rows = None, []
    return out


def register_paths(root: Path, cfg: dict[str, Any]) -> list[Path]:
    paths: list[Path] = []
    for pattern in cfg.get("registers") or []:
        paths += sorted(p for p in root.glob(pattern) if p.is_file())
    return paths


def status_word(cell: str) -> str:
    words = cell.replace("*", " ").split()
    return words[0].strip(".,:;") if words else ""


def decisions(root: Path, cfg: dict[str, Any]) -> list[dict[str, str]]:
    """Every register row whose first cell is an ID like B-01 or D-12.

    `has_status` is "yes" when the row's table has a status column. A log table without one
    (for example an approvals log of D- rows) is still read, so its IDs can be cited.
    """
    rows: list[dict[str, str]] = []
    for path in register_paths(root, cfg):
        for table in tables(read(path)):
            for r in table:
                first = next(iter(r.values()), "").strip("*` ")
                if ROW_ID.match(first):
                    rows.append({"id": first, "decision": r.get("decision", r.get("item", "")),
                                 "status": status_word(r.get("status", "")), "date": r.get("date", ""),
                                 "has_status": "yes" if "status" in r else "",
                                 "register": path.relative_to(root).as_posix()})
    return rows


def resolved(status: str, cfg: dict[str, Any]) -> bool:
    return status in (cfg.get("approved_words") or ["Approved"])


def playbook(root: Path) -> list[dict[str, Any]]:
    stages = []
    for table in tables(read(root / "founder" / "playbook.md")):
        for r in table:
            if r.get("#", "").isdigit() and "gate" in r:
                row = {"stage": int(r["#"]), "phase": r.get("phase", ""), "name": r.get("stage", ""),
                       "gate": r.get("gate", ""), "status": r.get("status", "")}
                if "evidence" in r:  # optional column: what shows the gate was met (decision IDs, files, links)
                    row["evidence"] = r["evidence"]
                stages.append(row)
    return stages


def epic_roles(root: Path) -> dict[str, str]:
    """Epic-to-role mapping from founder/team.md "## Epic ownership", the only copy."""
    text = read(root / "founder" / "team.md")
    block = text.split("## Epic ownership", 1)[1].split("\n## ", 1)[0] if "## Epic ownership" in text else ""
    roles: dict[str, str] = {}
    for line in block.splitlines():
        m = re.match(r"\s*-\s*(" + "|".join(ROLES) + r")\s*:\s*(.+)", line)
        if m:
            for code in re.findall(r"\b[A-Z]{2,5}\b", m.group(2)):
                roles[code] = m.group(1)
    return roles


def founder_items(root: Path) -> list[dict[str, str]]:
    text = read(root / "founder" / "status.md")
    if "## Open founder items" not in text:
        return []
    block = text.split("## Open founder items", 1)[1].split("\n## ", 1)[0]
    items = []
    for table in tables(block):
        for r in table:
            vals = list(r.values())
            items.append({"item": vals[0] if vals else "", "owner": r.get("owner", ""),
                          "needed_by": r.get("needed by", "")})
    return items


def slices(root: Path, cfg: dict[str, Any]) -> dict[str, Any]:
    """founder/slices.json: {"epics": {code: {name, goal}}, "slices": [...], "stories": [...]}."""
    try:
        data = json.loads(read(root / str(cfg.get("slices_file") or "founder/slices.json")) or "{}")
    except ValueError:
        data = {}
    return {"epics": data.get("epics") or {}, "slices": data.get("slices") or [], "stories": data.get("stories") or []}


def story_counts(s: dict[str, Any]) -> tuple[int, int, int]:
    """(criteria, done, tested) for a story; `done`/`tested` may be counts or lists of criterion numbers."""
    def n(v: Any) -> int:
        return len(v) if isinstance(v, list) else int(v or 0)
    return n(s.get("criteria")), n(s.get("done")), n(s.get("tested"))


def is_generated(path: str, cfg: dict[str, Any]) -> bool:
    return any(fnmatch.fnmatch(path, pat) or fnmatch.fnmatch(Path(path).name, pat)
               for pat in cfg.get("generated_paths") or [])


def dump(data: Any) -> str:
    return json.dumps(data, indent=1, ensure_ascii=False) + "\n"


def write_or_check(path: Path, data: Any, check: bool) -> int:
    """Write `data` as JSON, or with check=True return 1 if the file differs (CI drift check)."""
    text = dump(data)
    rel = path.name
    if check:
        if read(path) != text:
            print(f"drift: {rel} is out of date with its sources; run the generator and commit it")
            return 1
        print(f"{rel}: up to date")
        return 0
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {rel}")
    return 0
